package by.bsuir.request;
import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.*; import io.grpc.stub.StreamObserver; import jakarta.annotation.PreDestroy; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.time.Instant; import java.util.*; import java.util.concurrent.TimeUnit;
import org.springframework.kafka.annotation.KafkaListener;
@Service public class RepairRequestGrpcService extends RepairRequestServiceGrpc.RepairRequestServiceImplBase {
 
 private final JdbcTemplate jdbc; private final Jsons jsons; private final OutboxService outbox; private final ManagedChannel deviceChannel; private final DeviceServiceGrpc.DeviceServiceBlockingStub device;
 public RepairRequestGrpcService(JdbcTemplate jdbc,Jsons jsons,OutboxService outbox,@Value("${integration.device.host:localhost}")String host,@Value("${integration.device.port:9102}")int port){this.jdbc=jdbc;this.jsons=jsons;this.outbox=outbox;this.deviceChannel=ManagedChannelBuilder.forAddress(host,port).usePlaintext().intercept(GrpcCorrelation.client()).build();this.device=DeviceServiceGrpc.newBlockingStub(deviceChannel);}
 @KafkaListener(topics=EventTopics.WORK_ORDER,groupId="repair-request-projection") @Transactional public void consumeWorkOrderEvent(String raw){var envelope=jsons.read(raw);if(!"WorkOrderCostCalculated".equals(Objects.toString(envelope.get("eventType"))))return;UUID eventId=UUID.fromString(envelope.get("eventId").toString());if(jdbc.queryForObject("select count(*) from processed_events where event_id=?",Integer.class,eventId)>0)return;var payload=jsons.read(envelope.get("payload").toString());jdbc.update("update repair_requests set estimated_cost=?,updated_at=? where id=?",new BigDecimal(payload.get("totalAmount").toString()),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),UUID.fromString(payload.get("repairRequestId").toString()));jdbc.update("insert into processed_events(event_id,processed_at) values(?,?)",eventId,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));}
 @PreDestroy void close(){deviceChannel.shutdown();}
 @Override public void getRequest(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);var value=find(UUID.fromString(jsons.string(in,"id")));authorize(value,in);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void getRequestSnapshot(JsonMessage req,StreamObserver<JsonMessage> obs){try{jsons.reply(obs,find(UUID.fromString(jsons.string(jsons.read(req),"id"))));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void listRequests(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);StringBuilder sql=new StringBuilder("select id,client_id AS \"clientId\",device_id AS \"deviceId\",device_category_id AS \"deviceCategoryId\",status,priority,problem_description AS \"problemDescription\",estimated_cost AS \"estimatedCost\",created_at AS \"createdAt\",updated_at AS \"updatedAt\" from repair_requests where 1=1");List<Object> args=new ArrayList<>();String role=Objects.toString(in.get("role"),"CLIENT");if(role.equals("CLIENT")){sql.append(" and client_id=?");args.add(UUID.fromString(jsons.string(in,"currentUserId")));}add(sql,args,in,"status","status",false);add(sql,args,in,"categoryId","device_category_id",true);if(in.get("createdFrom")!=null){sql.append(" and created_at>=?");args.add(java.time.OffsetDateTime.ofInstant(Instant.parse(in.get("createdFrom").toString()),java.time.ZoneOffset.UTC));}if(in.get("createdTo")!=null){sql.append(" and created_at<=?");args.add(java.time.OffsetDateTime.ofInstant(Instant.parse(in.get("createdTo").toString()),java.time.ZoneOffset.UTC));}String field=switch(Objects.toString(in.getOrDefault("sortField","CREATED_AT"))){case "COST"->"estimated_cost";case "PRIORITY"->"priority";default->"created_at";};String dir="ASC".equals(Objects.toString(in.get("sortDirection")))?" asc":" desc";sql.append(" order by ").append(field).append(dir);int page=jsons.integer(in,"page",0),size=Math.min(100,Math.max(1,jsons.integer(in,"size",20)));var all=jdbc.queryForList(sql.toString(),args.toArray());int from=Math.min(page*size,all.size()),to=Math.min(from+size,all.size());jsons.reply(obs,Map.of("items",all.subList(from,to),"page",page,"size",size,"totalElements",all.size(),"totalPages",(all.size()+size-1)/size));}catch(Throwable e){jsons.fail(obs,e);}}
 private void add(StringBuilder sql,List<Object> args,Map<String,Object> in,String key,String column,boolean uuid){if(in.get(key)!=null){sql.append(" and ").append(column).append("=?");args.add(uuid?UUID.fromString(in.get(key).toString()):in.get(key).toString());}}
 @Override @Transactional public void createRequest(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID client=UUID.fromString(jsons.string(in,"currentUserId")),deviceId=UUID.fromString(jsons.string(in,"deviceId"));var ownership=jsons.read(device.withDeadlineAfter(1500,TimeUnit.MILLISECONDS).validateOwnership(jsons.write(Map.of("clientId",client,"deviceId",deviceId))).getJson());if(!Boolean.TRUE.equals(ownership.get("owned")))throw new SecurityException("Device belongs to another client");@SuppressWarnings("unchecked")var dv=(Map<String,Object>)ownership.get("device");UUID category=UUID.fromString(dv.get("categoryId").toString());String description=jsons.string(in,"problemDescription").trim();if(description.length()<10)throw new IllegalArgumentException("problemDescription must contain at least 10 characters");int priority=jsons.integer(in,"priority",3);if(priority<1||priority>5)throw new IllegalArgumentException("priority must be between 1 and 5");UUID id=UUID.randomUUID();var now=java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC);jdbc.update("insert into repair_requests(id,client_id,device_id,device_category_id,status,priority,problem_description,created_at,updated_at) values(?,?,?,?,?,?,?,?,?)",id,client,deviceId,category,"NEW",priority,description,now,now);history(id,null,"NEW",client);var value=find(id);outbox.enqueue(EventTopics.REQUEST,"RepairRequestCreated",id,value);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void changeStatus(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID id=UUID.fromString(jsons.string(in,"requestId"));var current=find(id);String from=current.get("status").toString(),to=jsons.string(in,"status");if(!DomainRules.requestTransition(from,to))throw new IllegalArgumentException("Status transition from "+from+" to "+to+" is not allowed");jdbc.update("update repair_requests set status=?,updated_at=? where id=?",to,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id);history(id,from,to,UUID.fromString(jsons.string(in,"currentUserId")));var value=find(id);outbox.enqueue(EventTopics.REQUEST,"RepairRequestStatusChanged",id,Map.of("requestId",id,"clientId",value.get("clientId"),"previousStatus",from,"currentStatus",to));jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 private void history(UUID request,String from,String to,UUID changedBy){jdbc.update("insert into repair_request_status_history(id,repair_request_id,previous_status,new_status,changed_by,changed_at) values(?,?,?,?,?,?)",UUID.randomUUID(),request,from,to,changedBy,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));}
 private Map<String,Object> find(UUID id){var rows=jdbc.queryForList("select id,client_id AS \"clientId\",device_id AS \"deviceId\",device_category_id AS \"deviceCategoryId\",status,priority,problem_description AS \"problemDescription\",estimated_cost AS \"estimatedCost\",created_at AS \"createdAt\",updated_at AS \"updatedAt\" from repair_requests where id=?",id);if(rows.isEmpty())throw Status.NOT_FOUND.withDescription("Repair request not found").asRuntimeException();return rows.get(0);}
 private void authorize(Map<String,Object> value,Map<String,Object> in){if("CLIENT".equals(Objects.toString(in.get("role")))&&!value.get("clientId").toString().equals(Objects.toString(in.get("currentUserId"))))throw new SecurityException("Client can access only own repair requests");}
}




